import os
import torch


class Config:
    """
    Configuration for the Decoupled Z-Scanning SegFormer (MiT-B2) pipeline.
    Central source of truth for all hyperparameters, paths, and constants.
    """

    # --- Directory Definitions ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_17"

    # Ensure working directory exists for caching and checkpoints
    os.makedirs(WORKING_DIR, exist_ok=True)

    # --- Metadata File Paths ---
    # Generated by the metadata script provided in the problem description
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VALID_METADATA_PATH = os.path.join(METADATA_DIR, "validation.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # --- Output Paths ---
    # The submission file must be in the home directory
    SUBMISSION_FILE = "submission.csv"
    # Model checkpoint path
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # --- Data Dimensions & processing ---
    TILE_SIZE = 512
    NUM_SLICES_PER_FRAGMENT = 65

    # --- Z-Scanning / Slab Generation Configuration ---

    # Training uses a fixed context window starting at slice 20.
    # This avoids "Wide Context" signal dilution (Lesson 00034).
    Z_START_TRAIN = 20

    # The total depth of the context window is 24 slices (e.g., 20 to 44).
    Z_CONTEXT_DEPTH = 24

    # We generate 3 input channels using overlapping MIPs (Maximum Intensity Projections).
    # Each tuple represents (relative_start_index, relative_end_index) from the Z_START.
    # Channel 1: Relative 0-12  -> Absolute 20-32 (12 slices)
    # Channel 2: Relative 6-18  -> Absolute 26-38 (12 slices)
    # Channel 3: Relative 12-24 -> Absolute 32-44 (12 slices)
    Z_SLAB_CHANNELS = [(0, 12), (6, 18), (12, 24)]

    # --- Inference Configuration ---

    # Multi-Pass Z-Scanning: We run the model at these offsets to detect ink
    # that wanders outside the fixed training window.
    # The outputs will be combined using Max-Fusion.
    Z_OFFSETS_INFERENCE = [16, 20, 24]

    # --- Model Hyperparameters ---
    # Using MiT-B2 to balance receptive field and prevent overfitting (Lesson 00040).
    MODEL_BACKBONE = "nvidia/mit-b2"
    PRETRAINED = True
    NUM_CLASSES = 1  # Binary segmentation (Ink vs No-Ink)

    # --- Training Hyperparameters ---
    SEED = 42
    # Conservative learning rate to prevent divergence (Lesson 00037)
    LEARNING_RATE = 6e-5
    # Batch size suited for A100 GPU
    BATCH_SIZE = 16
    NUM_EPOCHS = 15
    # Early stopping to prevent overfitting
    EARLY_STOPPING_PATIENCE = 4

    # --- Hardware & Compute ---
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Number of data loading workers (12 vCPUs available)
    NUM_WORKERS = 4

    # --- Validation ---
    # Threshold for converting probabilities to binary mask for F0.5 score
    THRESHOLD = 0.5
    # Only submit if validation score exceeds this baseline
    BASELINE_SCORE = 0.598
